"use client"

import * as React from "react"
import { useDirection } from "@/hooks/use-direction"
import {
  resolveEdgeSide,
  type EdgeSide,
} from "@/lib/direction"
import { cn } from "@/lib/utils"
import { XIcon } from "lucide-react"
import { Dialog as SheetPrimitive } from "radix-ui"

function Sheet({ ...props }: React.ComponentProps<typeof SheetPrimitive.Root>) {
  return <SheetPrimitive.Root data-slot="sheet" {...props} />
}

function SheetTrigger({
  className,
  ...props
}: React.ComponentProps<typeof SheetPrimitive.Trigger>) {
  return (
    <SheetPrimitive.Trigger
      data-slot="sheet-trigger"
      className={cn("cursor-pointer", className)}
      {...props}
    />
  )
}

function SheetClose({
  className,
  ...props
}: React.ComponentProps<typeof SheetPrimitive.Close>) {
  return (
    <SheetPrimitive.Close
      data-slot="sheet-close"
      className={cn("cursor-pointer", className)}
      {...props}
    />
  )
}

function SheetPortal({
  ...props
}: React.ComponentProps<typeof SheetPrimitive.Portal>) {
  return <SheetPrimitive.Portal data-slot="sheet-portal" {...props} />
}

function SheetOverlay({
  className,
  ...props
}: React.ComponentProps<typeof SheetPrimitive.Overlay>) {
  return (
    <SheetPrimitive.Overlay
      data-slot="sheet-overlay"
      className={cn(
        "fixed inset-0 z-50 bg-black/50 data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:animate-in data-[state=open]:fade-in-0",
        className
      )}
      {...props}
    />
  )
}

function SheetContent({
  className,
  children,
  side = "end",
  showCloseButton = true,
  ...props
}: React.ComponentProps<typeof SheetPrimitive.Content> & {
  /**
   * Prefer `start` / `end` so the edge flips with writing direction.
   * `left` / `right` stay physical (do not flip in RTL).
   */
  side?: EdgeSide
  showCloseButton?: boolean
}) {
  // Portal under <body> — resolve logical edges + set dir for RTL CSS.
  const { dir } = useDirection()
  const resolvedSide = resolveEdgeSide(side, dir, "right")

  return (
    <SheetPortal>
      <SheetOverlay />
      <SheetPrimitive.Content
        data-slot="sheet-content"
        dir={dir}
        className={cn(
          "fixed z-50 flex flex-col gap-4 bg-background shadow-lg transition ease-in-out data-[state=closed]:animate-out data-[state=closed]:duration-300 data-[state=open]:animate-in data-[state=open]:duration-500",
          resolvedSide === "right" &&
            "inset-y-0 right-0 h-full w-3/4 border-s data-[state=closed]:slide-out-to-right data-[state=open]:slide-in-from-right sm:max-w-sm",
          resolvedSide === "left" &&
            "inset-y-0 left-0 h-full w-3/4 border-e data-[state=closed]:slide-out-to-left data-[state=open]:slide-in-from-left sm:max-w-sm",
          resolvedSide === "top" &&
            "inset-x-0 top-0 h-auto border-b data-[state=closed]:slide-out-to-top data-[state=open]:slide-in-from-top",
          resolvedSide === "bottom" &&
            "inset-x-0 bottom-0 h-auto border-t data-[state=closed]:slide-out-to-bottom data-[state=open]:slide-in-from-bottom",
          className
        )}
        {...props}
      >
        {children}
        {showCloseButton && (
          <SheetPrimitive.Close className="absolute top-4 end-4 cursor-pointer rounded-xs opacity-70 ring-offset-background transition-opacity hover:opacity-100 focus:outline-hidden disabled:pointer-events-none data-[state=open]:bg-secondary">
            <XIcon className="size-4" />
            <span className="sr-only">Close</span>
          </SheetPrimitive.Close>
        )}
      </SheetPrimitive.Content>
    </SheetPortal>
  )
}

function SheetHeader({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="sheet-header"
      className={cn("flex flex-col gap-1.5 p-4", className)}
      {...props}
    />
  )
}

function SheetFooter({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="sheet-footer"
      className={cn("mt-auto flex flex-col gap-2 p-4", className)}
      {...props}
    />
  )
}

function SheetTitle({
  className,
  ...props
}: React.ComponentProps<typeof SheetPrimitive.Title>) {
  return (
    <SheetPrimitive.Title
      data-slot="sheet-title"
      className={cn("font-semibold text-foreground", className)}
      {...props}
    />
  )
}

function SheetDescription({
  className,
  ...props
}: React.ComponentProps<typeof SheetPrimitive.Description>) {
  return (
    <SheetPrimitive.Description
      data-slot="sheet-description"
      className={cn("text-sm text-muted-foreground", className)}
      {...props}
    />
  )
}

export {
  Sheet,
  SheetTrigger,
  SheetClose,
  SheetContent,
  SheetHeader,
  SheetFooter,
  SheetTitle,
  SheetDescription,
}

export type Direction = "ltr" | "rtl"

export const DEFAULT_DIRECTION: Direction = "ltr"

export function isDirection(value: unknown): value is Direction {
  return value === "ltr" || value === "rtl"
}

export function normalizeDirection(
  value: string | null | undefined,
  fallback: Direction = DEFAULT_DIRECTION
): Direction {
  if (value === "rtl" || value === "ltr") return value
  return fallback
}

export function isRtl(dir: Direction) {
  return dir === "rtl"
}

export function getOppositeDirection(dir: Direction): Direction {
  return dir === "rtl" ? "ltr" : "rtl"
}

export function getStartSide(dir: Direction): "left" | "right" {
  return dir === "rtl" ? "right" : "left"
}

export function getEndSide(dir: Direction): "left" | "right" {
  return dir === "rtl" ? "left" : "right"
}

export type EdgeSide = "top" | "bottom" | "left" | "right" | "start" | "end"

export type PhysicalEdgeSide = "top" | "bottom" | "left" | "right"

export function resolveEdgeSide(
  side: EdgeSide | undefined,
  dir: Direction,
  fallback: PhysicalEdgeSide = "bottom"
): PhysicalEdgeSide {
  const value = side ?? fallback
  if (value === "start") return getStartSide(dir)
  if (value === "end") return getEndSide(dir)
  return value
}

export function readElementDirection(
  el?: Element | null,
  fallback: Direction = DEFAULT_DIRECTION
): Direction {
  if (!el || typeof window === "undefined") return fallback
  const raw = getComputedStyle(el).direction
  return normalizeDirection(raw, fallback)
}

"use client"

import * as React from "react"

import {
  DEFAULT_DIRECTION,
  type Direction,
  isRtl,
  normalizeDirection,
  readElementDirection,
} from "@/lib/direction"

const DirectionContext = React.createContext<Direction | null>(null)

export function DirectionContextProvider({
  dir,
  children,
}: {
  dir: Direction
  children: React.ReactNode
}) {
  return (
    <DirectionContext.Provider value={dir}>{children}</DirectionContext.Provider>
  )
}

export function useDirection(): {
  dir: Direction
  isRtl: boolean
} {
  const fromContext = React.useContext(DirectionContext)
  const [inherited, setInherited] = React.useState<Direction>(DEFAULT_DIRECTION)

  React.useLayoutEffect(() => {
    if (fromContext) {
      setInherited(fromContext)
      return
    }
    setInherited(readElementDirection(document.documentElement))
  }, [fromContext])

  const dir = fromContext ?? inherited

  return {
    dir,
    isRtl: isRtl(dir),
  }
}

export function useDocumentDirection(): Direction {
  const [dir, setDir] = React.useState<Direction>(DEFAULT_DIRECTION)

  React.useEffect(() => {
    const root = document.documentElement
    const sync = () =>
      setDir(normalizeDirection(root.getAttribute("dir"), DEFAULT_DIRECTION))
    sync()
    const observer = new MutationObserver(sync)
    observer.observe(root, { attributes: true, attributeFilter: ["dir"] })
    return () => observer.disconnect()
  }, [])

  return dir
}

export { DirectionContext }
